// Recebe { clientes: [...] } do script Python e devolve 1 item por cliente valido
const entrada = $input.first().json;
const body = entrada.body || entrada;
const clientes = Array.isArray(body.clientes) ? body.clientes : [];

const emailValido = (e) => typeof e === 'string' && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e.trim());

const modelos = {
  conservador: {
    produto: 'CDB com liquidez diária',
    texto: 'Pelo seu perfil conservador, o foco é segurança e previsibilidade. Uma opção a considerar é um CDB com liquidez diária, que costuma permitir resgate rápido sem grandes oscilações.'
  },
  moderado: {
    produto: 'Carteira equilibrada (renda fixa + fundos)',
    texto: 'Pelo seu perfil moderado, vale buscar equilíbrio entre renda fixa e uma parcela menor em fundos de maior potencial de retorno.'
  },
  arrojado: {
    produto: 'Carteira com maior parcela em renda variável',
    texto: 'Pelo seu perfil arrojado, voce aceita mais oscilacao em busca de retorno maior. Uma opcao a considerar e ampliar a parcela em acoes e fundos de renda variável, mantendo uma reserva em renda fixa.'
  }
};

const saida = [];
const ignorados = [];

for (const c of clientes) {
  if (!emailValido(c.email)) { ignorados.push(c.nome || '(sem nome)'); continue; }
  const perfil = String(c.perfil || 'moderado').trim().toLowerCase();
  const m = modelos[perfil] || modelos.moderado;
  const nome = c.nome || 'cliente';
  saida.push({ json: {
    nome,
    email: c.email.trim(),
    perfil: modelos[perfil] ? perfil : 'moderado',
    saldo: c.saldo ?? null,
    produto: m.produto,
    assunto: `Sugestão de investimento: ${m.produto}`,
    html: `<p>Olá, ${nome}!</p><p>${m.texto}</p><p><small>Mensagem informativa e educacional. Não constitui recomendação individual de investimento.</small></p><p>Atenciosamente,<br>Sua equipe de investimentos</p>`
  }});
}

if (saida.length === 0) {
  return [{ json: { semClientes: true, ignorados } }];
}
return saida;
